@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_store_order(api_client, scenario_case, config_test_data):
    """
    Test the /store/order endpoint for various scenarios.
    """
    # Prepare request data
    request_data = {
        "id": scenario_case.get("id"),
        "petId": scenario_case.get("petId") or config_test_data.get("petId"),
        "quantity": scenario_case.get("quantity"),
    }
    if "shipDate" in scenario_case:
        request_data["shipDate"] = scenario_case["shipDate"]
    if "status" in scenario_case:
        request_data["status"] = scenario_case["status"]
    if "complete" in scenario_case:
        request_data["complete"] = scenario_case["complete"]

    # Validate request schema
