    assert validation_result["valid"], f"Request validation failed: {validation_result.get('message')}"

    # Make API request
    response = api_client.post(ENDPOINT, json=request_data)

    # Validate response status code
    assert response.status_code == scenario_case["statusCode"], f"Expected {scenario_case['statusCode']}, got {response.status_code}"

    # Validate response schema
    schema_validation_result = swagger_validator.validate_schema_by_response(ENDPOINT, METHOD, str(response.status_code), response)
    assert schema_validation_result["valid"], f"Response validation failed: {schema_validation_result.get('message')}"

